func NormalizeModeration(m *ModuleModeration) {
	if m == nil {
		return
	}

	// Enums: un PATCH directo puede dejar cualquiera de estos en `""` — bien
	// porque el cliente lo mandó vacío a propósito (el selector del dashboard
	// sin elegir), bien porque sólo tocó un hermano del mismo objeto anidado y
	// `encoding/json` rellenó el resto a su cero. En ambos casos `""` no es un
	// modo/acción real: el bot no tiene ninguna rama para él, así que el campo
	// queda "configurado" en apariencia sin ejecutar nunca nada. Se normaliza
	// al MISMO default que siembra un documento nuevo
	// (`mocks.NewModuleModeration`/`Default*`) — nunca se rechaza aquí; lo
	// imposible (una cadena que no es NINGÚN valor del enum) lo corta
	// `ValidateUpdateModuleModeration` antes de que el PATCH llegue a Mongo.
	if m.CommandMode == "" {
		m.CommandMode = ModerationCommandModeBoth
	}
	if m.Mute.Mode == "" {
		m.Mute.Mode = ModerationMuteModeAuto
	}
	if m.Automod.Mentions.Action == "" {
		m.Automod.Mentions.Action = AutomodActionDelete
	}
	if m.Automod.Words.Action == "" {
		m.Automod.Words.Action = AutomodActionDelete
	}
	if m.Automod.Invites.Action == "" {
		m.Automod.Invites.Action = AutomodActionDelete
	}
	if m.Automod.Spam.Action == "" {
		m.Automod.Spam.Action = AutomodActionDelete
	}
	if m.Automod.Duplicates.Action == "" {
		m.Automod.Duplicates.Action = AutomodActionDelete
	}
	if m.Automod.Caps.Action == "" {
		m.Automod.Caps.Action = AutomodActionDelete
	}
	if m.Automod.Links.Action == "" {
		m.Automod.Links.Action = AutomodActionDelete
	}
	if m.Automod.Emojis.Action == "" {
		m.Automod.Emojis.Action = AutomodActionDelete
	}
	if m.Automod.Attachments.Action == "" {
		m.Automod.Attachments.Action = AutomodActionDelete
	}
	if m.Raid.Action == "" {
		m.Raid.Action = ModerationRaidAlert
	}
	if m.Gate.Action == "" {
		m.Gate.Action = ModerationGateAlert
	}
	if m.Antinuke.Punishment == "" {
		m.Antinuke.Punishment = ModerationNukePunishStripRoles
	}
	for action, limit := range m.Antinuke.Limits {
		if limit.Punishment == "" {
			limit.Punishment = ModerationNukePunishInherit
			m.Antinuke.Limits[action] = limit
		}
	}

	normalizeModerationAccess(&m.CommandsGlobal)

