// ModerationLockdown mirrors `DBModuleModerationLockdown` (v3) — config del
// bloqueo de canales (`/lock`, `/unlock` y el lockdown del anti-raid). Los
// mensajes vacíos caen en el texto por defecto del módulo.
type ModerationLockdown struct {
	LockMessage    string   `bson:"lock_message"    json:"lock_message"`
	UnlockMessage  string   `bson:"unlock_message"  json:"unlock_message"`
	BypassRoles    []string `bson:"bypass_roles"    json:"bypass_roles"`
