		return zodItemError(moderationCommandModeMsg, "command_mode")
	}

	if body.CommandsGlobal != nil {
		if err := validateModerationAccessModes(body.CommandsGlobal, "commands_global"); err != nil {
			return err
		}
	}
	if body.Commands != nil {
		for name, cmd := range *body.Commands {
			if err := validateModerationAccessModes(&cmd.Access, "commands."+name+".access"); err != nil {
				return err
			}
		}
	}

	if body.Mute != nil && !moderationEnumOK(body.Mute.Mode, moderationMuteModeSet) {
		return zodItemError(moderationMuteModeMsg, "mute.mode")
	}

	if body.Automod != nil {
		for _, r := range []struct {
			action   dbguild.AutomodAction
			property string
		}{
			{body.Automod.Mentions.Action, "automod.mentions.action"},
			{body.Automod.Words.Action, "automod.words.action"},
			{body.Automod.Invites.Action, "automod.invites.action"},
			{body.Automod.Spam.Action, "automod.spam.action"},
			{body.Automod.Duplicates.Action, "automod.duplicates.action"},
			{body.Automod.Caps.Action, "automod.caps.action"},
			{body.Automod.Links.Action, "automod.links.action"},
			{body.Automod.Emojis.Action, "automod.emojis.action"},
			{body.Automod.Attachments.Action, "automod.attachments.action"},
		} {
			if !moderationEnumOK(r.action, automodActionSet) {
				return zodItemError(automodActionMsg, r.property)
			}
		}
	}

