		for i, ct := range body.Escalation.CountTypes {
			if !infractionCountableTypeSet[ct] {
				return zodItemError(infractionCountableTypeMsg, "escalation.count_types."+strconv.Itoa(i))
			}
		}
		for i, rule := range body.Escalation.Rules {
			if !moderationEscalationActionSet[rule.Action] {
				return zodItemError(moderationEscalationActionMsg, "escalation.rules."+strconv.Itoa(i)+".action")
			}
		}
	}

