				return zodItemError(moderationNukePunishmentOrInheritMsg, "antinuke.limits."+action+".punishment")
			}
		}
	}

	return nil
}

// validateModerationAccessModes rejects a `mode` (roles/channels/categories)
// that is neither "only" nor "all_except". Same moderationEnumOK semantics:
// "" passes (an omitted sibling in a partial nested object, or a real ""
// that NormalizeModeration replaces with "all_except").
func validateModerationAccessModes(a *dbguild.ModerationCommandAccess, prefix string) *apierrors.CustomError {
	for _, l := range []struct {
		mode     dbguild.ModerationAccessMode
		property string
	}{
		{a.Roles.Mode, prefix + ".roles.mode"},
		{a.Channels.Mode, prefix + ".channels.mode"},
		{a.Categories.Mode, prefix + ".categories.mode"},
	} {
		if !moderationEnumOK(l.mode, moderationAccessModeSet) {
			return zodItemError(moderationAccessModeMsg, l.property)
		}
	}
	return nil
}

