func validateModerationAccessModes(a *dbguild.ModerationCommandAccess, prefix string) *apierrors.CustomError {
	for _, l := range []struct {
		mode     dbguild.ModerationAccessMode
		property string
	}{
		{a.Roles.Mode, prefix + ".roles.mode"},
		{a.Channels.Mode, prefix + ".channels.mode"},
		{a.Categories.Mode, prefix + ".categories.mode"},
	} {
		if !moderationEnumOK(l.mode, moderationAccessModeSet) {
			return zodItemError(moderationAccessModeMsg, l.property)
		}
	}
	return nil
}

