package dbguild

import (
	"encoding/json"
	"strings"
	"testing"

	"go.mongodb.org/mongo-driver/v2/bson"
)

// v2Raw devuelve un subdoc crudo tal cual lo dejó el schema v2: sin ninguno de
// los siete bloques del v3, con las tres reglas de automod de entonces y sin
// `count_as_warn`. Es el documento que hay HOY en producción.
func v2Raw() bson.M {
	return bson.M{
		"schema_version":       int32(2),
		"enabled":              true,
		"command_mode":         "slash",
		"track_native_actions": true,
		"commands": bson.M{
			"ban": bson.M{"enabled": false, "use_global": true},
		},
		"automod": bson.M{
			"mentions": bson.M{"enabled": true, "action": "delete_warn", "timeout_ms": 60000, "max_mentions": 4},
			"words":    bson.M{"enabled": false, "action": "delete", "timeout_ms": 300000},
			"invites":  bson.M{"enabled": false, "action": "delete", "timeout_ms": 300000},
		},
	}
}

// TestMigrateModerationRaw_V2DocGetsV3Defaults 🛡️ — el caso central: un
// documento v2 pasa por la migración y sale con los defaults NO-CERO del v3
// puestos (ventanas, umbrales, `timeout_ms`, protecciones activas) y la versión
// sellada a 3. Sin esto, un decode directo al struct dejaría todo a 0 y el
// anti-raid se activaría con umbral 0 y ventana 0.
func TestMigrateModerationRaw_V2DocGetsV3Defaults(t *testing.T) {
	m := MigrateModerationRaw(v2Raw())
	NormalizeModeration(&m) // todo call site empareja las dos

	if m.SchemaVersion != SchemaVersionModeration {
		t.Fatalf("schema_version = %d, want %d", m.SchemaVersion, SchemaVersionModeration)
	}

	// Lo que ya existía sobrevive intacto.
	if !m.Enabled || m.CommandMode != ModerationCommandModeSlash {
		t.Fatalf("la migración pisó campos del v2: enabled=%v command_mode=%q", m.Enabled, m.CommandMode)
	}
	if m.Commands["ban"].Enabled {
		t.Fatalf("commands.ban.enabled = true, want false (config del v2 pisada)")
	}
	if !m.Automod.Mentions.Enabled || m.Automod.Mentions.Action != AutomodActionDeleteWarn ||
		m.Automod.Mentions.TimeoutMs != 60000 || m.Automod.Mentions.MaxMentions != 4 {
		t.Fatalf("automod.mentions pisado por el default: %+v", m.Automod.Mentions)
	}

	// Los 11 comandos del v3 se siembran; los del v2 no se tocan.
	if len(m.Commands) != len(ModerationCommandNames) {
		t.Fatalf("commands tiene %d entradas, want %d", len(m.Commands), len(ModerationCommandNames))
	}
	for _, name := range []string{"limpiar", "lock", "unlock", "slowmode", "vcmute", "vcunmute", "vcexpulsar", "mover", "nota", "caso", "raid"} {
		c, ok := m.Commands[name]
		if !ok {
			t.Fatalf("comando del v3 %q sin sembrar", name)
		}
		if !c.Enabled || !c.UseGlobal || !c.DmEnabled || c.Aliases == nil {
			t.Fatalf("commands[%s] = %+v, want activo + hereda global + DM + aliases []", name, c)
		}
	}

	// Las seis reglas nuevas de automod, con sus parámetros NO-cero.
	if m.Automod.Spam.MaxMessages != 5 || m.Automod.Spam.WindowMs != 5000 || !m.Automod.Spam.PurgeBurst {
		t.Fatalf("automod.spam = %+v, want 5/5000/purge_burst", m.Automod.Spam)
	}
	if m.Automod.Duplicates.MaxRepeats != 3 || m.Automod.Duplicates.WindowMs != 30000 {
		t.Fatalf("automod.duplicates = %+v, want 3/30000", m.Automod.Duplicates)
	}
	if m.Automod.Caps.MinLength != 10 || m.Automod.Caps.MaxPercent != 70 {
		t.Fatalf("automod.caps = %+v, want 10/70", m.Automod.Caps)
	}
	if m.Automod.Emojis.MaxEmojis != 10 {
		t.Fatalf("automod.emojis.max_emojis = %d, want 10", m.Automod.Emojis.MaxEmojis)
	}
	for name, timeout := range map[string]int{
		"spam":        m.Automod.Spam.TimeoutMs,
		"duplicates":  m.Automod.Duplicates.TimeoutMs,
		"caps":        m.Automod.Caps.TimeoutMs,
		"links":       m.Automod.Links.TimeoutMs,
		"emojis":      m.Automod.Emojis.TimeoutMs,
		"attachments": m.Automod.Attachments.TimeoutMs,
	} {
		if timeout != AutomodDefaultTimeoutMs {
			t.Fatalf("automod.%s.timeout_ms = %d, want %d (el default no-cero se perdió)", name, timeout, AutomodDefaultTimeoutMs)
		}
	}

	// Los siete bloques nuevos, con sus defaults no-cero.
	if !m.Protection.RespectHierarchy || !m.Protection.ProtectAdmins || !m.Protection.ProtectBots {
		t.Fatalf("protection = %+v, want la red de seguridad activa", m.Protection)
	}
	if m.Escalation.WindowMs != 30*24*60*60*1000 || len(m.Escalation.CountTypes) != 1 {
		t.Fatalf("escalation = %+v, want ventana de 30 días y count_types [warn]", m.Escalation)
	}
	if m.Effects.PurgeOnBan.Policy != ModerationEffectAsk || m.Effects.PurgeOnBanSeconds != 86400 {
		t.Fatalf("effects = %+v, want purge_on_ban ask + 86400 s", m.Effects)
	}
	if m.Raid.JoinThreshold != 10 || m.Raid.JoinWindowMs != 10000 || m.Raid.DurationMs != 600000 {
		t.Fatalf("raid = %+v, want 10/10000/600000", m.Raid)
	}
	if m.Gate.Action != ModerationGateAlert || !m.Gate.ExemptBots {
		t.Fatalf("gate = %+v, want alert + exempt_bots", m.Gate)
	}
	if m.Antinuke.Punishment != ModerationNukePunishStripRoles || len(m.Antinuke.Limits) != len(ModerationNukeActionNames) {
		t.Fatalf("antinuke = %+v, want strip_roles y las 13 acciones sembradas", m.Antinuke)
	}
	for _, action := range ModerationNukeActionNames {
		lim := m.Antinuke.Limits[string(action)]
		if lim.WindowMs != 60000 || lim.Max <= 0 || lim.Punishment != ModerationNukePunishInherit {
			t.Fatalf("antinuke.limits[%s] = %+v, want ventana 60000 / tope > 0 / inherit", action, lim)
		}
	}
	if m.Lockdown.BypassRoles == nil || m.Lockdown.ServerChannels == nil {
		t.Fatalf("lockdown = %+v, want listas []", m.Lockdown)
	}
}

// TestMigrateModerationRaw_Idempotent 🛡️ — migrar dos veces da el mismo
// resultado: el segundo paso ya no encuentra nada ausente y no toca nada.
func TestMigrateModerationRaw_Idempotent(t *testing.T) {
	first := MigrateModerationRaw(v2Raw())
	NormalizeModeration(&first)

	// Se vuelve a serializar a crudo, tal cual lo persistiría el repo, y se
	// migra otra vez.
	b, err := bson.Marshal(first)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var raw bson.M
	if err := bson.Unmarshal(b, &raw); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	second := MigrateModerationRaw(raw)
	NormalizeModeration(&second)

	firstJSON, _ := json.Marshal(first)
	secondJSON, _ := json.Marshal(second)
	if string(firstJSON) != string(secondJSON) {
		t.Fatalf("la migración no es idempotente:\n1ª: %s\n2ª: %s", firstJSON, secondJSON)
	}
}

// TestMigrateModerationRaw_KeepsHandPickedZeroes 🛡️ — la ausencia se detecta
// por la CLAVE del crudo, no por el valor cero del struct: un umbral que
// alguien puso a 0 A PROPÓSITO desde la dashboard NO se pisa con el default.
func TestMigrateModerationRaw_KeepsHandPickedZeroes(t *testing.T) {
	raw := v2Raw()
	raw["escalation"] = bson.M{
		"enabled":             true,
		"window_ms":           int32(0), // "cuenta todo el historial", a propósito
		"count_types":         bson.A{"warn", "kick"},
		"count_automod":       false,
		"reset_after_trigger": false,
		"rules":               bson.A{bson.M{"threshold": int32(3), "action": "kick", "duration_ms": int32(0)}},
	}
	raw["raid"] = bson.M{
		"enabled":        true,
		"join_threshold": int32(0), // anti-raid deliberadamente sin umbral
		"join_window_ms": int32(0),
		"action":         "lockdown",
	}
	raw["automod"] = bson.M{
		"mentions": bson.M{"enabled": true, "action": "delete", "timeout_ms": int32(1000)},
		"spam":     bson.M{"enabled": true, "action": "delete", "timeout_ms": int32(0), "max_messages": int32(0), "window_ms": int32(0)},
	}

	m := MigrateModerationRaw(raw)
	NormalizeModeration(&m)

	if m.Escalation.WindowMs != 0 || !m.Escalation.Enabled || m.Escalation.CountAutomod || m.Escalation.ResetAfterTrigger {
		t.Fatalf("escalation puesto a mano pisado por el default: %+v", m.Escalation)
	}
	if len(m.Escalation.Rules) != 1 || m.Escalation.Rules[0].Threshold != 3 {
		t.Fatalf("escalation.rules pisado: %+v", m.Escalation.Rules)
	}
	if m.Raid.JoinThreshold != 0 || m.Raid.JoinWindowMs != 0 || m.Raid.Action != ModerationRaidLockdown {
		t.Fatalf("raid puesto a mano pisado por el default: %+v", m.Raid)
	}
	if m.Automod.Spam.MaxMessages != 0 || m.Automod.Spam.WindowMs != 0 || m.Automod.Spam.TimeoutMs != 0 {
		t.Fatalf("automod.spam puesto a mano pisado por el default: %+v", m.Automod.Spam)
	}
	// Y las reglas que SÍ faltaban en ese `automod` recortado sí reciben default.
	if m.Automod.Words.TimeoutMs != AutomodDefaultTimeoutMs || m.Automod.Caps.MinLength != 10 {
		t.Fatalf("las reglas ausentes deberían llevar default: words=%+v caps=%+v", m.Automod.Words, m.Automod.Caps)
	}
}

// TestMigrateModerationRaw_NestedBsonD 🛡️ — la forma REAL que llega de Mongo:
// el driver v2 decodifica todo sub-documento anidado dentro de un `bson.M` como
// `bson.D`. Si la detección de bloques no lo contempla, cada lectura creería que
// `automod`/`antinuke` no existen y los pisaría con los defaults, borrando la
// configuración del servidor en cada GET.
func TestMigrateModerationRaw_NestedBsonD(t *testing.T) {
	// Se construye igual que lo haría el repo: documento → BSON → bson.M.
	doc := bson.M{"module_moderation": v2Raw()}
	b, err := bson.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var out struct {
		ModuleModeration bson.M `bson:"module_moderation"`
	}
	if err := bson.Unmarshal(b, &out); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if _, isD := out.ModuleModeration["automod"].(bson.D); !isD {
		t.Fatalf("precondición: se esperaba un bson.D anidado, got %T", out.ModuleModeration["automod"])
	}

	m := MigrateModerationRaw(out.ModuleModeration)
	NormalizeModeration(&m)

	if !m.Automod.Mentions.Enabled || m.Automod.Mentions.Action != AutomodActionDeleteWarn || m.Automod.Mentions.TimeoutMs != 60000 {
		t.Fatalf("automod.mentions se pisó con el default en la forma bson.D: %+v", m.Automod.Mentions)
	}
	// Y las reglas del v3, que sí faltaban, reciben su default no-cero.
	if m.Automod.Caps.MinLength != 10 || m.Automod.Spam.WindowMs != 5000 {
		t.Fatalf("las reglas del v3 no recibieron default: caps=%+v spam=%+v", m.Automod.Caps, m.Automod.Spam)
	}
}

// TestMigrateModerationRaw_PoisonedSchemaVersion 🛡️ — el "veneno" de tempvoice:
// un documento SELLADO con la versión actual pero SIN los bloques del v3 (una
// escritura estampó la versión sobre una forma sin migrar) se cura igual. La
// migración no tiene early-return por `schema_version` a propósito.
func TestMigrateModerationRaw_PoisonedSchemaVersion(t *testing.T) {
	raw := v2Raw()
	raw["schema_version"] = int32(SchemaVersionModeration)

	m := MigrateModerationRaw(raw)
	NormalizeModeration(&m)

	if m.Raid.JoinThreshold != 10 || m.Antinuke.Punishment != ModerationNukePunishStripRoles {
		t.Fatalf("un doc con la versión sellada pero sin migrar debe curarse igual: raid=%+v antinuke=%+v", m.Raid, m.Antinuke)
	}
	if !m.Protection.RespectHierarchy {
		t.Fatalf("protection sin rellenar en un doc envenenado: %+v", m.Protection)
	}
}

// TestMigrateModerationRaw_NullBlockCountsAsAbsent 🛡️ — un bloque presente
// pero que NO es un sub-documento (`null`, un escalar suelto) cuenta como
// ausente: no hay configuración que conservar.
func TestMigrateModerationRaw_NullBlockCountsAsAbsent(t *testing.T) {
	raw := v2Raw()
	raw["gate"] = nil
	raw["antinuke"] = "basura"

	m := MigrateModerationRaw(raw)
	NormalizeModeration(&m)

	if !m.Gate.ExemptBots || m.Gate.Action != ModerationGateAlert {
		t.Fatalf("gate null debe caer en el default, got %+v", m.Gate)
	}
	if len(m.Antinuke.Limits) != len(ModerationNukeActionNames) {
		t.Fatalf("antinuke basura debe caer en el default, got %+v", m.Antinuke)
	}
}

// TestMigrateModerationRaw_AntinukeBackfillsMissingLimits 🛡️ — con `antinuke`
// ya presente sólo se añaden las acciones que falten; los topes ya ajustados
// por el servidor no se tocan.
func TestMigrateModerationRaw_AntinukeBackfillsMissingLimits(t *testing.T) {
	raw := v2Raw()
	raw["antinuke"] = bson.M{
		"enabled":    true,
		"punishment": "ban",
		"limits": bson.M{
			string(ModerationNukeChannelDelete): bson.M{
				"enabled": true, "max": int32(1), "window_ms": int32(5000), "punishment": "kick",
			},
		},
	}

	m := MigrateModerationRaw(raw)
	NormalizeModeration(&m)

	kept := m.Antinuke.Limits[string(ModerationNukeChannelDelete)]
	if !kept.Enabled || kept.Max != 1 || kept.WindowMs != 5000 ||
		kept.Punishment != ModerationNukePunishmentOrInherit(ModerationNukePunishKick) {
		t.Fatalf("el límite ya ajustado se pisó: %+v", kept)
	}
	if m.Antinuke.Punishment != ModerationNukePunishBan {
		t.Fatalf("antinuke.punishment = %q, want ban (preservado)", m.Antinuke.Punishment)
	}
	if len(m.Antinuke.Limits) != len(ModerationNukeActionNames) {
		t.Fatalf("faltan límites por sembrar: %d de %d", len(m.Antinuke.Limits), len(ModerationNukeActionNames))
	}
	if got := m.Antinuke.Limits[string(ModerationNukeGuildUpdate)]; got.Max != 2 || got.Enabled {
		t.Fatalf("límite sembrado guild_update = %+v, want max 2 y apagado", got)
	}
}

// TestMigrateModerationRaw_EmptyRawIsAllDefaults 🛡️ — un subdoc vacío sale con
// TODO por defecto (el repo sólo llega aquí con un doc no vacío, pero la
// función debe aguantarlo).
func TestMigrateModerationRaw_EmptyRawIsAllDefaults(t *testing.T) {
	m := MigrateModerationRaw(bson.M{})
	NormalizeModeration(&m)

	if m.CommandMode != ModerationCommandModeBoth {
		t.Fatalf("command_mode = %q, want both", m.CommandMode)
	}
	if len(m.Commands) != len(ModerationCommandNames) {
		t.Fatalf("commands = %d entradas, want %d", len(m.Commands), len(ModerationCommandNames))
	}
	if m.Automod.Mentions.TimeoutMs != AutomodDefaultTimeoutMs || m.Effects.PurgeOnKickSeconds != 3600 {
		t.Fatalf("defaults no aplicados sobre un subdoc vacío: %+v / %+v", m.Automod.Mentions, m.Effects)
	}
	if m.SchemaVersion != SchemaVersionModeration {
		t.Fatalf("schema_version = %d, want %d", m.SchemaVersion, SchemaVersionModeration)
	}
}

// TestModerationRawSchemaVersion 🛡️ — tolera las formas int/int32/int64/float64
// que producen los decoders de Mongo/JSON; ausente → 0.
func TestModerationRawSchemaVersion(t *testing.T) {
	cases := []struct {
		val  any
		want int
	}{
		{int(2), 2}, {int32(2), 2}, {int64(2), 2}, {float64(2), 2}, {nil, 0}, {"2", 0},
	}
	for _, c := range cases {
		raw := bson.M{}
		if c.val != nil {
			raw["schema_version"] = c.val
		}
		if got := ModerationRawSchemaVersion(raw); got != c.want {
			t.Fatalf("ModerationRawSchemaVersion(%v) = %d, want %d", c.val, got, c.want)
		}
	}
}

// TestNormalizeModeration_V3NilCollections 🛡️ — un módulo del v3 decodificado
// con las colecciones nuevas a nil sale con `[]` / `{}`, nunca `null`, y los
// nullables nuevos (`raid.alert_*`, `gate.alert_channel_id`, `antinuke.alert_*`)
// se quedan en `null`.
func TestNormalizeModeration_V3NilCollections(t *testing.T) {
	m := ModuleModeration{SchemaVersion: SchemaVersionModeration}
	NormalizeModeration(&m)

	for name, s := range map[string][]string{
		"protection.immune_roles":            m.Protection.ImmuneRoles,
		"protection.immune_users":            m.Protection.ImmuneUsers,
		"protection.hierarchy_bypass_roles":  m.Protection.HierarchyBypassRoles,
		"raid.lockdown_channels":             m.Raid.LockdownChannels,
		"gate.blocked_name_patterns":         m.Gate.BlockedNamePatterns,
		"antinuke.trusted_users":             m.Antinuke.TrustedUsers,
		"antinuke.trusted_roles":             m.Antinuke.TrustedRoles,
		"lockdown.bypass_roles":              m.Lockdown.BypassRoles,
		"lockdown.server_channels":           m.Lockdown.ServerChannels,
		"automod.links.allowed_domains":      m.Automod.Links.AllowedDomains,
		"automod.links.blocked_domains":      m.Automod.Links.BlockedDomains,
		"automod.attachments.blocked_ext":    m.Automod.Attachments.BlockedExtensions,
		"automod.spam.exempt_roles":          m.Automod.Spam.ExemptRoles,
		"automod.duplicates.exempt_channels": m.Automod.Duplicates.ExemptChannels,
		"automod.caps.exempt_roles":          m.Automod.Caps.ExemptRoles,
		"automod.emojis.exempt_channels":     m.Automod.Emojis.ExemptChannels,
	} {
		if s == nil {
			t.Fatalf("normalize dejó nil en %s", name)
		}
	}
	if m.Escalation.CountTypes == nil || m.Escalation.Rules == nil {
		t.Fatalf("normalize dejó nil en escalation: %+v", m.Escalation)
	}
	if m.Antinuke.Limits == nil {
		t.Fatalf("normalize dejó nil en antinuke.limits")
	}

	b, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	js := string(b)
	for _, bad := range []string{
		`"immune_roles":null`, `"count_types":null`, `"rules":null`, `"limits":null`,
		`"lockdown_channels":null`, `"blocked_name_patterns":null`,
		`"allowed_domains":null`, `"blocked_extensions":null`, `"bypass_roles":null`,
	} {
		if strings.Contains(js, bad) {
			t.Fatalf("el JSON normalizado no debe contener %s:\n%s", bad, js)
		}
	}
	// Los nullables nuevos SÍ se quedan en null: es como se codifica "usa el
	// canal de mod-log" / "sin mención".
	for _, want := range []string{`"alert_channel_id":null`, `"alert_role_id":null`} {
		if !strings.Contains(js, want) {
			t.Fatalf("falta %s en el JSON normalizado:\n%s", want, js)
		}
	}
}

// TestNormalizeModeration_FlowsBackfillsCollections 🛡️ — `Flows` decodificado a
// nil sale como `[]` no-nulo (nunca `null`), y las colecciones internas de
// cada flujo (`Setup`/`Conditions`/`Steps`) que hayan decodificado a nil
// también se rellenan. `Branches` es la EXCEPCIÓN: nil se queda nil (ver el
// siguiente test).
func TestNormalizeModeration_FlowsBackfillsCollections(t *testing.T) {
	m := &ModuleModeration{SchemaVersion: SchemaVersionModeration}
	NormalizeModeration(m)
	if m.Flows == nil || len(m.Flows) != 0 {
		t.Fatalf("Flows = %+v, want [] no-nulo", m.Flows)
	}

	m2 := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows:         []ModerationFlow{{ID: "f1", Trigger: ModerationFlowTrigger{Type: "message_sent"}}},
	}
	NormalizeModeration(m2)
	f := m2.Flows[0]
	if f.Setup == nil || f.Conditions == nil || f.Steps == nil {
		t.Fatalf("Setup/Conditions/Steps = %+v/%+v/%+v, se esperaban listas vacías no-nulas", f.Setup, f.Conditions, f.Steps)
	}
	if f.Trigger.Params == nil {
		t.Fatal("Trigger.Params = nil, se esperaba un mapa vacío no-nulo")
	}
	if f.Scope.Channels.IDs == nil || f.Scope.Categories.IDs == nil || f.Scope.Roles.IDs == nil {
		t.Fatalf("scope access-list ids = %+v, se esperaban listas vacías no-nulas", f.Scope)
	}

	b, err := json.Marshal(m2)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	js := string(b)
	for _, want := range []string{`"setup":[]`, `"conditions":[]`, `"steps":[]`, `"params":{}`} {
		if !strings.Contains(js, want) {
			t.Fatalf("el JSON normalizado no contiene %s:\n%s", want, js)
		}
	}
}

// TestNormalizeModeration_FlowsBranchesOmittedWhenNil 🛡️ — `branches` ausente
// (nil) es un estado LEGÍTIMO («sin ramas»): NormalizeModeration no lo fuerza
// a `[]`, y el JSON omite la clave por completo — mismo criterio que
// `Automation.Branches` (§1 del contrato: "Ausente o vacío = sin ramas").
func TestNormalizeModeration_FlowsBranchesOmittedWhenNil(t *testing.T) {
	m := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows:         []ModerationFlow{{ID: "f1"}},
	}
	NormalizeModeration(m)
	if m.Flows[0].Branches != nil {
		t.Fatalf("Branches = %+v, want nil (normalize no debe forzarlo a [])", m.Flows[0].Branches)
	}
	b, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if strings.Contains(string(b), `"branches"`) {
		t.Fatalf("el JSON no debe contener la clave \"branches\" cuando Branches es nil:\n%s", b)
	}
}

// TestNormalizeModeration_FlowsFlattensBSONParams 🛡️ — el caso que motiva todo
// el aplanado (mismo que TestNormalizeAutomation_FlattensBSONDocuments): un
// subdocumento decodificado de Mongo llega como `bson.D`/`bson.A`. Sin
// aplanarlo, `json.Marshal` lo escribe como `[{"Key":…,"Value":…}]` — corrupto
// para el módulo y para el merge del PATCH, que también pasa por JSON. Cubre
// los CUATRO sitios donde vive un `params` libre: el trigger, una condición
// raíz, un paso de `setup` y un paso/condición dentro de una rama.
func TestNormalizeModeration_FlowsFlattensBSONParams(t *testing.T) {
	m := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows: []ModerationFlow{{
			ID: "f1",
			Trigger: ModerationFlowTrigger{
				Type:   "message_sent",
				Params: map[string]any{"nested": bson.D{{Key: "deep", Value: bson.D{{Key: "n", Value: 1}}}}},
			},
			Setup: []ModerationFlowStep{{
				ID: "s1", Type: "set_variable",
				Params: map[string]any{"embed": bson.D{{Key: "title", Value: "hola"}}},
			}},
			Conditions: []ModerationFlowCondition{{
				ID: "c1", Type: "message_contains",
				Params: map[string]any{"values": bson.A{"a", "b"}},
			}},
			Steps: []ModerationFlowStep{{
				ID: "st1", Type: "warn_member",
				Params: map[string]any{"opts": bson.D{{Key: "notify_dm", Value: true}}},
			}},
			Branches: []ModerationFlowBranch{{
				ID: "b1",
				Conditions: []ModerationFlowCondition{{
					ID: "bc1", Type: "chance",
					Params: map[string]any{"cfg": bson.D{{Key: "percent", Value: 50}}},
				}},
				Steps: []ModerationFlowStep{{
					ID: "bs1", Type: "kick_member",
					Params: map[string]any{"tags": bson.A{"x"}},
				}},
			}},
		}},
	}
	NormalizeModeration(m)

	assertFlatObject := func(label string, params map[string]any) {
		t.Helper()
		raw, err := json.Marshal(params)
		if err != nil {
			t.Fatalf("%s: json.Marshal: %v", label, err)
		}
		if strings.Contains(string(raw), `"Key"`) || strings.Contains(string(raw), `"Value"`) {
			t.Fatalf("%s salió sin aplanar (todavía bson.D): %s", label, raw)
		}
	}

	f := m.Flows[0]
	assertFlatObject("trigger.params", f.Trigger.Params)
	assertFlatObject("setup[0].params", f.Setup[0].Params)
	assertFlatObject("conditions[0].params", f.Conditions[0].Params)
	assertFlatObject("steps[0].params", f.Steps[0].Params)
	assertFlatObject("branches[0].conditions[0].params", f.Branches[0].Conditions[0].Params)
	assertFlatObject("branches[0].steps[0].params", f.Branches[0].Steps[0].Params)

	// El anidado profundo (trigger.params.nested.deep) también debe quedar
	// como objeto JSON normal, no sólo el primer nivel.
	nested, ok := f.Trigger.Params["nested"].(map[string]any)
	if !ok {
		t.Fatalf("trigger.params.nested salió como %T, se esperaba un objeto JSON", f.Trigger.Params["nested"])
	}
	if _, ok := nested["deep"].(map[string]any); !ok {
		t.Fatalf("trigger.params.nested.deep salió como %T, el aplanado no es recursivo", nested["deep"])
	}
}

func TestNormalizeModeration_FlowsIdempotent(t *testing.T) {
	m := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows: []ModerationFlow{{
			ID:      "f1",
			Trigger: ModerationFlowTrigger{Type: "message_sent", Params: map[string]any{"n": bson.D{{Key: "k", Value: "v"}}}},
		}},
	}
	NormalizeModeration(m)
	first, _ := json.Marshal(m)
	NormalizeModeration(m)
	second, _ := json.Marshal(m)
	if string(first) != string(second) {
		t.Fatalf("no es idempotente:\n1: %s\n2: %s", first, second)
	}
}

