func TestValidateUpdateModuleModeration_NilAndEmpty(t *testing.T) {
	if verr := ValidateUpdateModuleModeration(nil); verr != nil {
		t.Fatalf("nil body: %v", verr)
	}
	if verr := ValidateUpdateModuleModeration(&UpdateModuleModerationBody{}); verr != nil {
		t.Fatalf("empty body: %v", verr)
	}
}

// TestValidateUpdateModuleModeration_EmptyEnumsPass 🛡️ — un "" en un enum de
// bloque parcial NO se rechaza: puede ser el cero de Go de un hermano que el
// cliente ni mencionó. NormalizeModeration lo repone a su default una vez el
// merge aterriza en Mongo.
func TestValidateUpdateModuleModeration_EmptyEnumsPass(t *testing.T) {
	body := &UpdateModuleModerationBody{
		CommandMode: ptr(dbguild.ModerationCommandMode("")),
		Mute:        &dbguild.ModerationMute{Mode: ""},
		Raid:        &dbguild.ModerationRaid{Action: ""},
		Gate:        &dbguild.ModerationGate{Action: ""},
		Antinuke: &dbguild.ModerationAntinuke{
			Punishment: "",
			Limits: map[string]dbguild.ModerationNukeLimit{
				"channel_delete": {Punishment: ""},
			},
		},
		CommandsGlobal: &dbguild.ModerationCommandAccess{
			Roles: dbguild.ModerationAccessList{Mode: ""},
		},
	}
	if verr := ValidateUpdateModuleModeration(body); verr != nil {
		t.Fatalf("empty enums should pass validation (normalized later): %v", verr)
	}
}

func TestValidateUpdateModuleModeration_InvalidCommandMode(t *testing.T) {
	body := &UpdateModuleModerationBody{CommandMode: ptr(dbguild.ModerationCommandMode("bogus"))}
	assertZod(t, ValidateUpdateModuleModeration(body), moderationCommandModeMsg, "command_mode")
}

