	body := &UpdateModuleModerationBody{Antinuke: &dbguild.ModerationAntinuke{Punishment: "bogus"}}
	assertZod(t, ValidateUpdateModuleModeration(body), moderationNukePunishmentMsg, "antinuke.punishment")
}

func TestValidateUpdateModuleModeration_UnknownAntinukeLimitKey(t *testing.T) {
	body := &UpdateModuleModerationBody{
		Antinuke: &dbguild.ModerationAntinuke{
			Limits: map[string]dbguild.ModerationNukeLimit{"not_a_real_action": {}},
		},
	}
	assertZod(t, ValidateUpdateModuleModeration(body), moderationNukeActionKeyMsg, "antinuke.limits.not_a_real_action")
}

func TestValidateUpdateModuleModeration_InvalidAntinukeLimitPunishment(t *testing.T) {
	body := &UpdateModuleModerationBody{
		Antinuke: &dbguild.ModerationAntinuke{
			Limits: map[string]dbguild.ModerationNukeLimit{"channel_delete": {Punishment: "bogus"}},
		},
	}
	assertZod(t, ValidateUpdateModuleModeration(body), moderationNukePunishmentOrInheritMsg, "antinuke.limits.channel_delete.punishment")
}

func TestValidateUpdateModuleModeration_InvalidCountType(t *testing.T) {
	body := &UpdateModuleModerationBody{
		Escalation: &dbguild.ModerationEscalation{
			CountTypes: []dbguild.InfractionCountableType{"bogus"},
		},
	}
	assertZod(t, ValidateUpdateModuleModeration(body), infractionCountableTypeMsg, "escalation.count_types.0")
}

// TestValidateUpdateModuleModeration_EmptyEscalationRuleActionRejected 🛡️ —
// a diferencia del resto de enums, `escalation.rules` sustituye la lista
// ENTERA: cada elemento es una fila completa que el cliente eligió mandar, no
// puede ser un hermano omitido. Un peldaño sin acción es una sanción que
// nunca se ejecuta, así que se rechaza en vez de normalizarse.
func TestValidateUpdateModuleModeration_EmptyEscalationRuleActionRejected(t *testing.T) {
	body := &UpdateModuleModerationBody{
		Escalation: &dbguild.ModerationEscalation{
			Rules: []dbguild.ModerationEscalationRule{{Threshold: 3, Action: ""}},
		},
	}
	assertZod(t, ValidateUpdateModuleModeration(body), moderationEscalationActionMsg, "escalation.rules.0.action")
}

func TestValidateUpdateModuleModeration_ValidEscalationRulePasses(t *testing.T) {
	body := &UpdateModuleModerationBody{
		Escalation: &dbguild.ModerationEscalation{
			Rules: []dbguild.ModerationEscalationRule{{Threshold: 3, Action: dbguild.ModerationEscalationMute}},
		},
	}
	if verr := ValidateUpdateModuleModeration(body); verr != nil {
		t.Fatalf("valid rule action: %v", verr)
	}
}

