// ── Normalización ───────────────────────────────────────────────────────────

// NormalizeModeration backfills every collection field that decoded as `nil`
// (from a partial Mongo doc or a legacy cache entry) with a non-nil empty
// value, mirroring the zod `.default([])` / `.default({})`. This keeps the JSON
// body emitting `[]` / `{}` instead of `null` — the exact shape the Node
// service produces after re-parsing through `moduleModerationSchema`.
//
// Scalars and nullable pointers are left untouched: a stored `null` stays
// `null`, matching the `string | null` fields (`log_channel_id`, `mute.role_id`,
// each command's `dm_embed.color`, los `alert_*` del v3). Idempotent.
//
// OJO: normalizar NO es migrar. Aquí sólo se rellenan colecciones vacías; los
// defaults NO-cero del v3 (`timeout_ms`, ventanas, umbrales) los pone
// `MigrateModerationRaw`.
func NormalizeModeration(m *ModuleModeration) {
	if m == nil {
		return
	}

	// Enums: un PATCH directo puede dejar cualquiera de estos en `""` — bien
	// porque el cliente lo mandó vacío a propósito (el selector del dashboard
	// sin elegir), bien porque sólo tocó un hermano del mismo objeto anidado y
	// `encoding/json` rellenó el resto a su cero. En ambos casos `""` no es un
	// modo/acción real: el bot no tiene ninguna rama para él, así que el campo
	// queda "configurado" en apariencia sin ejecutar nunca nada. Se normaliza
	// al MISMO default que siembra un documento nuevo
	// (`mocks.NewModuleModeration`/`Default*`) — nunca se rechaza aquí; lo
	// imposible (una cadena que no es NINGÚN valor del enum) lo corta
	// `ValidateUpdateModuleModeration` antes de que el PATCH llegue a Mongo.
	if m.CommandMode == "" {
		m.CommandMode = ModerationCommandModeBoth
	}
	if m.Mute.Mode == "" {
		m.Mute.Mode = ModerationMuteModeAuto
	}
	if m.Automod.Mentions.Action == "" {
		m.Automod.Mentions.Action = AutomodActionDelete
	}
	if m.Automod.Words.Action == "" {
		m.Automod.Words.Action = AutomodActionDelete
	}
	if m.Automod.Invites.Action == "" {
		m.Automod.Invites.Action = AutomodActionDelete
	}
	if m.Automod.Spam.Action == "" {
		m.Automod.Spam.Action = AutomodActionDelete
	}
	if m.Automod.Duplicates.Action == "" {
		m.Automod.Duplicates.Action = AutomodActionDelete
	}
	if m.Automod.Caps.Action == "" {
		m.Automod.Caps.Action = AutomodActionDelete
	}
	if m.Automod.Links.Action == "" {
		m.Automod.Links.Action = AutomodActionDelete
	}
	if m.Automod.Emojis.Action == "" {
		m.Automod.Emojis.Action = AutomodActionDelete
	}
	if m.Automod.Attachments.Action == "" {
		m.Automod.Attachments.Action = AutomodActionDelete
	}
	if m.Raid.Action == "" {
		m.Raid.Action = ModerationRaidAlert
	}
	if m.Gate.Action == "" {
		m.Gate.Action = ModerationGateAlert
	}
	if m.Antinuke.Punishment == "" {
		m.Antinuke.Punishment = ModerationNukePunishStripRoles
	}
	for action, limit := range m.Antinuke.Limits {
		if limit.Punishment == "" {
			limit.Punishment = ModerationNukePunishInherit
			m.Antinuke.Limits[action] = limit
		}
	}

	normalizeModerationAccess(&m.CommandsGlobal)

	if m.Commands == nil {
		m.Commands = map[string]ModerationCommand{}
	} else {
		for k, v := range m.Commands {
			normalizeModerationAccess(&v.Access)
			v.Aliases = ensureModerationStrSlice(v.Aliases)
			m.Commands[k] = v
		}
	}

	m.Automod.Mentions.ExemptRoles = ensureModerationStrSlice(m.Automod.Mentions.ExemptRoles)
	m.Automod.Mentions.ExemptChannels = ensureModerationStrSlice(m.Automod.Mentions.ExemptChannels)
	m.Automod.Mentions.BlockedUsers = ensureModerationStrSlice(m.Automod.Mentions.BlockedUsers)
	m.Automod.Mentions.BlockedRoles = ensureModerationStrSlice(m.Automod.Mentions.BlockedRoles)

	m.Automod.Words.ExemptRoles = ensureModerationStrSlice(m.Automod.Words.ExemptRoles)
	m.Automod.Words.ExemptChannels = ensureModerationStrSlice(m.Automod.Words.ExemptChannels)
	m.Automod.Words.Words = ensureModerationStrSlice(m.Automod.Words.Words)

	m.Automod.Invites.ExemptRoles = ensureModerationStrSlice(m.Automod.Invites.ExemptRoles)
	m.Automod.Invites.ExemptChannels = ensureModerationStrSlice(m.Automod.Invites.ExemptChannels)
	m.Automod.Invites.AllowedCodes = ensureModerationStrSlice(m.Automod.Invites.AllowedCodes)

	// v3: las seis reglas nuevas.
	m.Automod.Spam.ExemptRoles = ensureModerationStrSlice(m.Automod.Spam.ExemptRoles)
	m.Automod.Spam.ExemptChannels = ensureModerationStrSlice(m.Automod.Spam.ExemptChannels)

	m.Automod.Duplicates.ExemptRoles = ensureModerationStrSlice(m.Automod.Duplicates.ExemptRoles)
	m.Automod.Duplicates.ExemptChannels = ensureModerationStrSlice(m.Automod.Duplicates.ExemptChannels)

	m.Automod.Caps.ExemptRoles = ensureModerationStrSlice(m.Automod.Caps.ExemptRoles)
	m.Automod.Caps.ExemptChannels = ensureModerationStrSlice(m.Automod.Caps.ExemptChannels)

	m.Automod.Links.ExemptRoles = ensureModerationStrSlice(m.Automod.Links.ExemptRoles)
	m.Automod.Links.ExemptChannels = ensureModerationStrSlice(m.Automod.Links.ExemptChannels)
	m.Automod.Links.AllowedDomains = ensureModerationStrSlice(m.Automod.Links.AllowedDomains)
	m.Automod.Links.BlockedDomains = ensureModerationStrSlice(m.Automod.Links.BlockedDomains)

	m.Automod.Emojis.ExemptRoles = ensureModerationStrSlice(m.Automod.Emojis.ExemptRoles)
	m.Automod.Emojis.ExemptChannels = ensureModerationStrSlice(m.Automod.Emojis.ExemptChannels)

	m.Automod.Attachments.ExemptRoles = ensureModerationStrSlice(m.Automod.Attachments.ExemptRoles)
	m.Automod.Attachments.ExemptChannels = ensureModerationStrSlice(m.Automod.Attachments.ExemptChannels)
	m.Automod.Attachments.BlockedExtensions = ensureModerationStrSlice(m.Automod.Attachments.BlockedExtensions)

	// v3: bloques nuevos de nivel superior.
	m.Protection.ImmuneRoles = ensureModerationStrSlice(m.Protection.ImmuneRoles)
	m.Protection.ImmuneUsers = ensureModerationStrSlice(m.Protection.ImmuneUsers)
	m.Protection.HierarchyBypassRoles = ensureModerationStrSlice(m.Protection.HierarchyBypassRoles)

package validations

import (
	"strconv"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleModerationBody mirrors the Node `updateModuleModerationSchema`
// (a `.strict()` object of `.optional()` fields). The handler decodes this
// with `DisallowUnknownFields` (matching the zod `.strict()` — unknown
// keys top-level OR nested are a 400) and then re-decodes the SAME raw
// body as `map[string]any`, which the repository merges into the existing
// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the
// body is left alone; an explicit `false`/`0`/`""`/`null` is applied and
// overrides the stored value; nested objects (`commands_global`, `mute`,
// `automod`) recurse; the `commands` map merges per-key; slices replace
// wholesale.
//
// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
// / `updated_at` — those are stamped by the repo on every write. Every
// other READ field IS patchable here (the READ and PATCH catalogs
// otherwise match).
//
// `log_channel_id` is the only TOP-LEVEL nullable string (`string |
// null`). Because merge is presence-based, sending `null` clears it to
// null and omitting the key preserves the stored value — exactly like
// Node's `mergeDeep`, with no special-case handling in this struct. The
// nested nullables (`mute.role_id`, each command's `dm_embed.color`)
// ride inside their parent structs and are merged recursively.
//
// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
// presence-based behaviour):
//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
//     present nested object (Node's `commandAccessUpdateSchema` /
//     `automod*` rule schemas are `.strict()` with every field
//     required), so a partial nested object that Node would 400 is
//     accepted here and the missing leaves stay zero — the same
//     non-strict-required behaviour every Go module body has.
//   - The zod value constraints (`dm_embed.content` max 4000) are NOT
//     enforced here. Same as every other Go module body.
//
// Cada clave de nivel superior del schema DEBE tener su puntero aquí: si falta
// una, el PATCH de la dashboard se come un 400 "unknown field" (el handler
// decodifica con `DisallowUnknownFields`). Por eso los siete bloques del v3
// (`protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
// `lockdown`) están listados igual que `automod` — y `flows` (v4) igual.
//
// `Flows` reutiliza `dbguild.ModerationFlow` TAL CUAL (mismo precedente que
// `Creators *[]dbguild.TempvoiceCreator` / `TicketTypes *[]dbguild.TicketsType`
// / `TicketTypes *[]dbguild.ModmailTicketType`), no un tipo "Body" duplicado:
// el struct de dominio YA tiene exactamente la forma que la dashboard envía
// (§5.3 del contrato de flujos: el PATCH sustituye el array ENTERO, así que
// cada flujo llega completo, con `id`/`created_at`/`updated_at` incluidos).
// Los `params` de trigger/condiciones/pasos siguen siendo `map[string]any`
// libre — su forma la valida el catálogo compartido, no Go — así que
// `DisallowUnknownFields` no los toca; sí rechaza cualquier clave desconocida
// a nivel de `ModerationFlow`/`ModerationFlowScope`/etc., que es justo lo que
// se quiere.
type UpdateModuleModerationBody struct {
	Enabled            *bool                                 `json:"enabled,omitempty"`
	CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
	CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
	Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
	LogChannelID       *string                               `json:"log_channel_id,omitempty"`
	TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
	Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
	Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
	Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
	Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
	Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
	Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
	Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
	Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
	Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
}

// ── Enum sets ────────────────────────────────────────────────────────────

var moderationCommandModeSet = map[dbguild.ModerationCommandMode]bool{
	dbguild.ModerationCommandModeSlash:  true,
	dbguild.ModerationCommandModePrefix: true,
	dbguild.ModerationCommandModeBoth:   true,
}

var moderationAccessModeSet = map[dbguild.ModerationAccessMode]bool{
	dbguild.ModerationAccessOnly:      true,
	dbguild.ModerationAccessAllExcept: true,
}

var moderationMuteModeSet = map[dbguild.ModerationMuteMode]bool{
	dbguild.ModerationMuteModeAuto:    true,
	dbguild.ModerationMuteModeTimeout: true,
	dbguild.ModerationMuteModeRole:    true,
}

var automodActionSet = map[dbguild.AutomodAction]bool{
	dbguild.AutomodActionDelete:        true,
	dbguild.AutomodActionDeleteWarn:    true,
	dbguild.AutomodActionDeleteTimeout: true,
	dbguild.AutomodActionDeleteKick:    true,
	dbguild.AutomodActionDeleteBan:     true,
}

var moderationEscalationActionSet = map[dbguild.ModerationEscalationAction]bool{
	dbguild.ModerationEscalationMute:     true,
	dbguild.ModerationEscalationTempmute: true,
	dbguild.ModerationEscalationKick:     true,
	dbguild.ModerationEscalationTempban:  true,
	dbguild.ModerationEscalationBan:      true,
}

var infractionCountableTypeSet = map[dbguild.InfractionCountableType]bool{
	dbguild.InfractionCountableWarn:     true,
	dbguild.InfractionCountableNote:     true,
	dbguild.InfractionCountableMute:     true,
	dbguild.InfractionCountableTempmute: true,
	dbguild.InfractionCountableKick:     true,
	dbguild.InfractionCountableBan:      true,
	dbguild.InfractionCountableTempban:  true,
}

var moderationRaidActionSet = map[dbguild.ModerationRaidAction]bool{
	dbguild.ModerationRaidAlert:    true,
	dbguild.ModerationRaidLockdown: true,
	dbguild.ModerationRaidKick:     true,
	dbguild.ModerationRaidBan:      true,
}

var moderationGateActionSet = map[dbguild.ModerationGateAction]bool{
	dbguild.ModerationGateAlert: true,
	dbguild.ModerationGateKick:  true,
	dbguild.ModerationGateBan:   true,
	dbguild.ModerationGateMute:  true,
}

var moderationNukePunishmentSet = map[dbguild.ModerationNukePunishment]bool{
	dbguild.ModerationNukePunishAlert:      true,
	dbguild.ModerationNukePunishStripRoles: true,
	dbguild.ModerationNukePunishKick:       true,
	dbguild.ModerationNukePunishBan:        true,
}

// moderationNukePunishmentOrInheritSet es moderationNukePunishmentSet más
// `inherit` — el único valor que `ModerationNukePunishmentOrInherit` añade
// sobre `ModerationNukePunishment` (ver el comentario del tipo en
// module_moderation.go).
var moderationNukePunishmentOrInheritSet = map[dbguild.ModerationNukePunishmentOrInherit]bool{
	dbguild.ModerationNukePunishmentOrInherit(dbguild.ModerationNukePunishAlert):      true,
	dbguild.ModerationNukePunishmentOrInherit(dbguild.ModerationNukePunishStripRoles): true,
	dbguild.ModerationNukePunishmentOrInherit(dbguild.ModerationNukePunishKick):       true,
	dbguild.ModerationNukePunishmentOrInherit(dbguild.ModerationNukePunishBan):        true,
	dbguild.ModerationNukePunishInherit:                                              true,
}

// moderationNukeActionSet es el catálogo de claves válidas de
// `antinuke.limits` (el mismo que siembra `DefaultModerationNukeLimits`), en
// forma de `map[string]bool` porque el mapa del PATCH llega con claves
// `string` sueltas — no hay un tipo dedicado a nivel de mapa que Go pueda
// comprobar por sí solo.
var moderationNukeActionSet = func() map[string]bool {
	out := make(map[string]bool, len(dbguild.ModerationNukeActionNames))
	for _, a := range dbguild.ModerationNukeActionNames {
		out[string(a)] = true
	}
	return out
}()

const (
	moderationCommandModeMsg             = `Invalid option: expected one of "slash"|"prefix"|"both"`
	moderationAccessModeMsg              = `Invalid option: expected one of "only"|"all_except"`
	moderationMuteModeMsg                = `Invalid option: expected one of "auto"|"timeout"|"role"`
	automodActionMsg                     = `Invalid option: expected one of "delete"|"delete_warn"|"delete_timeout"|"delete_kick"|"delete_ban"`
	moderationEscalationActionMsg        = `Invalid option: expected one of "mute"|"tempmute"|"kick"|"tempban"|"ban"`
	infractionCountableTypeMsg           = `Invalid option: expected one of "warn"|"note"|"mute"|"tempmute"|"kick"|"ban"|"tempban"`
	moderationRaidActionMsg              = `Invalid option: expected one of "alert"|"lockdown"|"kick"|"ban"`
	moderationGateActionMsg              = `Invalid option: expected one of "alert"|"kick"|"ban"|"mute"`
	moderationNukePunishmentMsg          = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"`
	moderationNukePunishmentOrInheritMsg = `Invalid option: expected one of "alert"|"strip_roles"|"kick"|"ban"|"inherit"`
	moderationNukeActionKeyMsg           = `Invalid key: expected one of the watched antinuke actions`
)

// moderationEnumOK reports whether an optional enum value is either empty or
// a member of `valid`. `""` is NOT rejected here: in a partial nested object
// (`mute`, `automod.*`, `raid`, `gate`, `antinuke`, the per-axis `mode`s…)
// it can be Go's zero value for a sibling the client never mentioned —
// `encoding/json` fills the rest of the struct with zeroes regardless — so
// treating it as an error would 400 legitimate partial PATCHes. If it turns
// out to be a REAL `""` the client sent on purpose, `NormalizeModeration`
// replaces it with the same default a brand-new document is seeded with once
// the merge lands. Only a non-empty, unrecognised string is "lo imposible":
// the bot has no branch for it, so persisting it verbatim would silently do
// nothing forever while the field looks configured.
func moderationEnumOK[T ~string](v T, valid map[T]bool) bool {
	return v == "" || valid[v]
}

// ValidateUpdateModuleModeration aplica la validación que faltaba por
// completo en el servidor: el zod del dashboard revalida cada enum en su
// propio servidor, pero eso sólo cubre a quien entra POR el dashboard — este
// endpoint acepta un PATCH directo con la credencial de api-db, y hasta ahora
// nada impedía guardar un `command_mode`, una acción de AutoMod o un castigo
// de antinuke que no es NINGÚN valor real del enum (mismo hueco que
// `ValidateUpdateModuleGreeter`/`ValidateUpdateModuleTTS` cierran para sus
// verticales).
//
// `escalation.count_types` y `escalation.rules` son la EXCEPCIÓN a la regla
// de "`""` no se rechaza": el PATCH sustituye la lista ENTERA, así que cada
// elemento es una fila completa que el cliente eligió mandar — igual que
// `ValidateModmailTicketTypes` rechaza un `ticket_types[].id` en blanco, un
// `count_types[i]` o un `rules[i].action` vacío no puede ser un hermano
// omitido: no hay ningún default sensato para "el peldaño N sanciona con
// ''", así que se rechaza aquí en vez de dejarlo pasar para luego
// normalizarlo a ciegas.
func ValidateUpdateModuleModeration(body *UpdateModuleModerationBody) *apierrors.CustomError {
	if body == nil {
		return nil
	}

	if body.CommandMode != nil && !moderationEnumOK(*body.CommandMode, moderationCommandModeSet) {
		return zodItemError(moderationCommandModeMsg, "command_mode")
	}

	if body.CommandsGlobal != nil {
		if err := validateModerationAccessModes(body.CommandsGlobal, "commands_global"); err != nil {
			return err
		}
	}
	if body.Commands != nil {
		for name, cmd := range *body.Commands {
			if err := validateModerationAccessModes(&cmd.Access, "commands."+name+".access"); err != nil {
				return err
			}
		}
	}

	if body.Mute != nil && !moderationEnumOK(body.Mute.Mode, moderationMuteModeSet) {
		return zodItemError(moderationMuteModeMsg, "mute.mode")
	}

	if body.Automod != nil {
		for _, r := range []struct {
			action   dbguild.AutomodAction
			property string
		}{
			{body.Automod.Mentions.Action, "automod.mentions.action"},
			{body.Automod.Words.Action, "automod.words.action"},
			{body.Automod.Invites.Action, "automod.invites.action"},
			{body.Automod.Spam.Action, "automod.spam.action"},
			{body.Automod.Duplicates.Action, "automod.duplicates.action"},
			{body.Automod.Caps.Action, "automod.caps.action"},
			{body.Automod.Links.Action, "automod.links.action"},
			{body.Automod.Emojis.Action, "automod.emojis.action"},
			{body.Automod.Attachments.Action, "automod.attachments.action"},
		} {
			if !moderationEnumOK(r.action, automodActionSet) {
				return zodItemError(automodActionMsg, r.property)
			}
		}
	}

	if body.Escalation != nil {
		for i, ct := range body.Escalation.CountTypes {
			if !infractionCountableTypeSet[ct] {
				return zodItemError(infractionCountableTypeMsg, "escalation.count_types."+strconv.Itoa(i))
			}
		}
		for i, rule := range body.Escalation.Rules {
			if !moderationEscalationActionSet[rule.Action] {
				return zodItemError(moderationEscalationActionMsg, "escalation.rules."+strconv.Itoa(i)+".action")
			}
		}
	}

	if body.Raid != nil && !moderationEnumOK(body.Raid.Action, moderationRaidActionSet) {
		return zodItemError(moderationRaidActionMsg, "raid.action")
	}

	if body.Gate != nil && !moderationEnumOK(body.Gate.Action, moderationGateActionSet) {
		return zodItemError(moderationGateActionMsg, "gate.action")
	}

	if body.Antinuke != nil {
		if !moderationEnumOK(body.Antinuke.Punishment, moderationNukePunishmentSet) {
			return zodItemError(moderationNukePunishmentMsg, "antinuke.punishment")
		}
		for action, limit := range body.Antinuke.Limits {
			if !moderationNukeActionSet[action] {
				return zodItemError(moderationNukeActionKeyMsg, "antinuke.limits."+action)
			}
			if !moderationEnumOK(limit.Punishment, moderationNukePunishmentOrInheritSet) {
				return zodItemError(moderationNukePunishmentOrInheritMsg, "antinuke.limits."+action+".punishment")
			}
		}
	}

	return nil
}

// validateModerationAccessModes rejects a `mode` (roles/channels/categories)
// that is neither "only" nor "all_except". Same moderationEnumOK semantics:
// "" passes (an omitted sibling in a partial nested object, or a real ""
// that NormalizeModeration replaces with "all_except").
func validateModerationAccessModes(a *dbguild.ModerationCommandAccess, prefix string) *apierrors.CustomError {
	for _, l := range []struct {
		mode     dbguild.ModerationAccessMode
		property string
	}{
		{a.Roles.Mode, prefix + ".roles.mode"},
		{a.Channels.Mode, prefix + ".channels.mode"},
		{a.Categories.Mode, prefix + ".categories.mode"},
	} {
		if !moderationEnumOK(l.mode, moderationAccessModeSet) {
			return zodItemError(moderationAccessModeMsg, l.property)
		}
	}
	return nil
}

// `{}` is a no-op that still bumps schema_version + updated_at (Node returns
// 200). A missing guild → 400 MODULE_NOT_FOUND with `data:null`.
func (h *ModuleModerationHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModeration]()
	ctx := c.Context()

	var body validations.UpdateModuleModerationBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// The decode only checks the SHAPE (enums bind as their underlying
	// string). The VALUE constraints — command_mode/mute.mode/automod
	// actions/raid.action/gate.action/antinuke punishments being one of the
	// actual enum members — did not exist in any server layer: this endpoint
	// accepts a direct PATCH with the api-db credential, bypassing the
	// dashboard's zod entirely, and nothing stopped a config the bot has no
	// code path for.
	if verr := validations.ValidateUpdateModuleModeration(&body); verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	// Re-decode the (already validated) body as a raw map so key presence
	// survives — explicit false/0/null must reach the merge (Node parity).
	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)

