// normalizeModerationAccess backfills the three access lists of a
// command-access block: each ID slice so it serialises as `[]`, and an empty
// `mode` to `all_except` (the same unrestricted default `ModerationAccessDefault`
// seeds) — same reasoning as the top-level enum block above.
func normalizeModerationAccess(a *ModerationCommandAccess) {
	normalizeModerationAccessList(&a.Roles)
	normalizeModerationAccessList(&a.Channels)
	normalizeModerationAccessList(&a.Categories)
}

func normalizeModerationAccessList(l *ModerationAccessList) {
	if l.Mode == "" {
		l.Mode = ModerationAccessAllExcept
	}
	l.IDs = ensureModerationStrSlice(l.IDs)
}

func ensureModerationStrSlice(s []string) []string {
	if s == nil {
		return []string{}
	}
	return s
}
